/*
 * A272799  Numbers k such that 2*k - 1 and 2*k + 1 are squarefree.
 * https://oeis.org/A272799
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 166, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   ensure_capacity, is_squarefree
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by scanning: a(n) is the nth positive integer k such that
   2*k-1 and 2*k+1 are squarefree (OEIS A272799). */

#include <stddef.h>
#include <stdbool.h>
#include "../utils/is_squarefree.h"
#include "../utils/ensure_capacity.h"

seq_t a(idx_t n)
{
    if (n < 1) return 0;

    static seq_t *cache = NULL;
    static size_t cache_len = 0, cache_cap = 0;
    static idx_t next_k = 1;

    while (cache_len < n) {
        seq_t two_k_minus1 = ((seq_t)next_k << 1) - 1;
        seq_t two_k_plus1   = two_k_minus1 + 2;
        if (is_squarefree(two_k_minus1) && is_squarefree(two_k_plus1)) {
            /* Ensure capacity for another element */
            ensure_capacity(cache_len + 1, &cache_cap, (void **)&cache, sizeof(seq_t));
            cache[cache_len++] = next_k;
        }
        next_k++;
    }

    return cache[n - 1];
}
